using System.Collections.Generic;
using UnityEngine;

// Distance-driven gait, planted feet and articulated joints; gameplay stays in native physics.
public sealed class CrewMotion : MonoBehaviour {
 sealed class Limb {public Transform upper,lower,end;public Vector3 home,plant,target;public bool planted;public float a,b;}
 sealed class Part {public Transform t;public Vector3 p;public Quaternion q;}
 Limb[] legs=new Limb[2],arms=new Limb[2];List<Part> body=new List<Part>();List<Material> materials=new List<Material>();Transform rig;float phase,recoil,landing,fallSpeed,smoothedSpeed,pelvisDrop;int children;
 public bool Armed=true,Interacting,Firing;public float Reload;public Vector3 Aim;public Transform Grip{get{return arms[0].end;}}
 public float KneeFlex{get;private set;}public float GaitPhase{get{return phase;}} public float MaxPlantSlip{get;private set;}public string State{get;private set;}="IDLE";
 public static CrewMotion Create(Transform root){var old=root.GetComponent<CrewMotion>();if(old!=null)return old;var m=root.gameObject.AddComponent<CrewMotion>();m.Build();return m;}
 Material M(Color c,float metal=.1f){var m=ProductionMaterials.Create(c,metal,.35f,0,0,metal<.2f&&c.maxColorComponent>.15f);materials.Add(m);return m;}
 void Build(){rig=JointMotion.Joint("ARTICULATED SUIT / hips knees elbows ankles",transform,Vector3.zero);rig.gameObject.layer=transform.gameObject.layer;Material fabric=M(new Color(.27f,.33f,.36f)),armor=M(new Color(.7f,.73f,.7f),.3f),rubber=M(new Color(.025f,.037f,.046f)),orange=M(new Color(.8f,.21f,.035f));
  foreach(Transform t in transform)if(t.name=="Boot"||t.name=="Glove and arm"||t.name=="Shoulder armor"||t.name=="Knee armor"||t.name=="Boot sole"){foreach(var r in t.GetComponentsInChildren<Renderer>())r.enabled=false;}
  for(int i=0;i<2;i++){float side=i==0?-1:1;legs[i]=MakeLimb("Leg "+i,new Vector3(side*.165f,-.24f,0),.34f,.36f,.105f,fabric,armor);var l=legs[i];JointMotion.Piece("Knee cap",l.lower,PrimitiveType.Sphere,new Vector3(0,-.015f,-.055f),new Vector3(.17f,.15f,.12f),armor);JointMotion.Piece("Boot",l.end,PrimitiveType.Cube,new Vector3(0,-.035f,-.055f),new Vector3(.19f,.10f,.30f),rubber);JointMotion.Piece("Boot toe guard",l.end,PrimitiveType.Cube,new Vector3(0,0,-.14f),new Vector3(.18f,.055f,.10f),armor);l.home=new Vector3(side*.165f,-.81f,-.025f);
   arms[i]=MakeLimb("Arm "+i,new Vector3(side*.33f,.25f,0),.28f,.29f,.09f,fabric,armor);JointMotion.Piece("Glove",arms[i].end,PrimitiveType.Sphere,Vector3.down*.015f,new Vector3(.13f,.15f,.14f),rubber);JointMotion.Piece("Shoulder shell",arms[i].upper,PrimitiveType.Sphere,new Vector3(0,-.035f,0),new Vector3(.22f,.17f,.24f),armor);JointMotion.Piece("Forearm safety band",arms[i].lower,PrimitiveType.Cylinder,new Vector3(0,-.12f,0),new Vector3(.15f,.035f,.15f),orange);
  }CacheBody();
 }
 Limb MakeLimb(string name,Vector3 anchor,float a,float b,float width,Material fabric,Material armor){var limb=new Limb{a=a,b=b};limb.upper=JointMotion.Joint(name+" / proximal joint",rig,anchor);limb.lower=JointMotion.Joint(name+" / distal joint",limb.upper,Vector3.down*a);limb.end=JointMotion.Joint(name+" / endpoint",limb.lower,Vector3.down*b);JointMotion.Piece("Pressure fabric segment",limb.upper,PrimitiveType.Capsule,Vector3.down*a*.5f,new Vector3(width*1.5f,a*.63f,width*1.5f),fabric);JointMotion.Piece("Rigid lower armor",limb.lower,PrimitiveType.Capsule,Vector3.down*b*.5f,new Vector3(width*1.55f,b*.60f,width*1.55f),armor);JointMotion.Piece("Joint seal",limb.lower,PrimitiveType.Sphere,Vector3.zero,Vector3.one*width*1.5f,fabric);return limb;}
 void CacheBody(){body.Clear();foreach(Transform t in transform){if(t==rig||t.name=="Boot"||t.name=="Glove and arm"||t.name=="PULSE CARBINE / animated muzzle")continue;body.Add(new Part{t=t,p=t.localPosition,q=t.localRotation});}children=transform.childCount;}
 public void Kick(){recoil=1;}
 public void ResetPose(){phase=0;smoothedSpeed=pelvisDrop=0;if(rig!=null)rig.localPosition=Vector3.zero;foreach(var l in legs)if(l!=null)l.planted=false;MaxPlantSlip=0;}
 public void Shift(Vector3 d){foreach(var l in legs)l.plant-=d;}
 public void SeatPose(bool driver){rig.localPosition=Vector3.zero;pelvisDrop=0;State=driver?"DRIVING":"PASSENGER";foreach(var p in body){if(p.t==null)continue;p.t.localPosition=p.p;p.t.localRotation=p.q;}for(int i=0;i<2;i++){float side=i==0?-1:1;var l=legs[i];l.planted=false;JointMotion.Solve(transform,l.upper,l.lower,l.end,transform.TransformPoint(new Vector3(side*.18f,-.56f,-.48f)),transform.TransformDirection(Vector3.back),l.a,l.b);var a=arms[i];Vector3 hand=driver?new Vector3(side*.28f,.09f,-.48f):new Vector3(side*.20f,-.20f,-.34f);JointMotion.Solve(transform,a.upper,a.lower,a.end,transform.TransformPoint(hand),transform.TransformDirection(new Vector3(side,-.2f,.5f)),a.a,a.b);}}
 public void Pose(float dt,Vector3 velocity,bool running,PlanetExpedition terrain,bool grounded){if(rig==null)return;if(children!=transform.childCount)CacheBody();Vector3 up=transform.up,tangent=Vector3.ProjectOnPlane(velocity,up);float speed=tangent.magnitude;smoothedSpeed=Mathf.Lerp(smoothedSpeed,speed,1-Mathf.Exp(-12*dt));float run=running?Mathf.Clamp01(smoothedSpeed/4):0,move=Mathf.Clamp01(smoothedSpeed/.65f);State=!grounded?"AIRBORNE":speed<.3f?"IDLE":running?"RUNNING":"WALKING";if(grounded&&fallSpeed< -1)landing=Mathf.Clamp01(-fallSpeed/5);fallSpeed=Vector3.Dot(velocity,up);landing=Mathf.MoveTowards(landing,0,dt*4);recoil=Mathf.MoveTowards(recoil,0,dt*7);
  float terrainSlope=grounded?Mathf.Abs(terrain.Alt(transform.position+transform.forward*.3f)-terrain.Alt(transform.position-transform.forward*.3f))/.6f:0;float stride=Mathf.Lerp(1.8f,2.8f,run)/Mathf.Clamp(1+terrainSlope*.45f,1,1.35f),duty=Mathf.Lerp(.52f,.34f,run);if(grounded)phase+=smoothedSpeed*dt/Mathf.Max(.2f,stride);Vector3 localMove=transform.InverseTransformDirection(tangent);if(localMove.sqrMagnitude<.001f)localMove=Vector3.back;localMove.y=0;localMove.Normalize();KneeFlex=0;rig.localPosition=Vector3.zero;float requiredDrop=0;
  for(int i=0;i<2;i++){var l=legs[i];float t=Mathf.Repeat(phase+i*.5f,1),swing=Mathf.Clamp01((t-duty)/(1-duty));bool stance=t<duty&&grounded;float half=stride*duty/(2*transform.lossyScale.y);float travel=stance?Mathf.Lerp(half,-half,t/duty):Mathf.Lerp(-half,half,Mathf.SmoothStep(0,1,swing));Vector3 target=l.home+localMove*travel*move;target.y+=Mathf.Sin(swing*Mathf.PI)*Mathf.Lerp(.12f,.27f,run)*move;if(!grounded){l.planted=false;target=l.home+Vector3.up*(.14f+i*.04f)+Vector3.forward*(i==0?.1f:-.12f);}Vector3 world=transform.TransformPoint(target);
   if(grounded){world-=up*(terrain.Alt(world)-.065f);if(!stance)world+=up*Mathf.Sin(swing*Mathf.PI)*Mathf.Lerp(.14f,.29f,run)*move;if(stance){if(!l.planted){l.plant=world;l.planted=true;}Vector3 drift=Vector3.ProjectOnPlane(world-l.plant,up);if(speed<.3f||drift.magnitude>.45f*transform.lossyScale.y||Vector3.Distance(l.upper.position-up*.24f,l.plant)>(l.a+l.b)*transform.lossyScale.y)l.plant=Vector3.Lerp(l.plant,world,1-Mathf.Exp(-16*dt));world=l.plant;}else l.planted=false;}
   l.target=world;Vector3 delta=l.upper.position-world;float reach=(l.a+l.b)*transform.lossyScale.y*.99f,horizontal=Vector3.ProjectOnPlane(delta,up).sqrMagnitude;float vertical=Mathf.Sqrt(Mathf.Max(.01f,reach*reach-horizontal));requiredDrop=Mathf.Max(requiredDrop,Vector3.Dot(delta,up)-vertical);
  }
  float wantedDrop=grounded?Mathf.Clamp(requiredDrop,0,.28f):0;pelvisDrop=wantedDrop>pelvisDrop?wantedDrop:Mathf.MoveTowards(pelvisDrop,wantedDrop,dt*.8f);rig.localPosition=Vector3.down*(pelvisDrop/transform.lossyScale.y);
  for(int i=0;i<2;i++){var l=legs[i];JointMotion.Solve(transform,l.upper,l.lower,l.end,l.target,transform.TransformDirection(Vector3.back),l.a,l.b);
   if(grounded){Vector3 across=transform.right*.09f,ahead=transform.forward*.09f;float dx=terrain.Alt(l.target+across)-terrain.Alt(l.target-across),dz=terrain.Alt(l.target+ahead)-terrain.Alt(l.target-ahead);Vector3 normal=(up-transform.right*(dx/.18f)-transform.forward*(dz/.18f)).normalized;normal=Vector3.RotateTowards(up,normal,32*Mathf.Deg2Rad,0);l.end.rotation=Quaternion.FromToRotation(up,normal)*transform.rotation;}
   KneeFlex=Mathf.Max(KneeFlex,Quaternion.Angle(l.upper.rotation,l.lower.rotation));if(l.planted)MaxPlantSlip=Mathf.Max(MaxPlantSlip,Vector3.Distance(l.end.position,l.plant));
  }

  float bob=(grounded?Mathf.Cos(phase*Mathf.PI*4)*.017f*move:-.035f)-landing*.055f,lean=-run*8;float aimPitch=Armed?Mathf.Clamp(Mathf.Asin(Mathf.Clamp(transform.InverseTransformDirection(Aim).y,-1,1))*Mathf.Rad2Deg,-45,45):0;Quaternion tilt=Quaternion.Euler(lean+aimPitch*.15f,Mathf.Sin(phase*Mathf.PI*2)*move*2,Mathf.Sin(phase*Mathf.PI*2)*move*1.4f);foreach(var p in body){if(p.t==null)continue;p.t.localPosition=new Vector3(0,-.14f,0)+tilt*(p.p-new Vector3(0,-.14f,0))+Vector3.up*(bob-pelvisDrop/transform.lossyScale.y);p.t.localRotation=tilt*p.q;}
  for(int i=0;i<2;i++){var a=arms[i];Vector3 target;float side=i==0?-1:1;if(Armed){target=i==0?new Vector3(-.29f,.07f,-.48f):new Vector3(.05f,.12f,-.45f);target.z+=recoil*.09f;target.y+=recoil*.025f;if(run>.2f&&!Firing&&Reload<=0){Vector3 carry=i==0?new Vector3(-.27f,-.10f,-.26f):new Vector3(.35f,-.20f,-Mathf.Sin(phase*Mathf.PI*2+Mathf.PI)*.20f);target=Vector3.Lerp(target,carry,run);}target=new Vector3(0,.2f,0)+Quaternion.Euler(aimPitch,0,0)*(target-new Vector3(0,.2f,0));if(Reload>0){float t=1-Mathf.Clamp01(Reload/1.45f);if(i==1)target=Vector3.Lerp(target,new Vector3(-.2f,-.13f,-.30f),Mathf.Sin(t*Mathf.PI));else target+=new Vector3(.03f,.08f,.10f)*Mathf.Sin(t*Mathf.PI);}}else target=new Vector3(side*.35f,-.20f,-Mathf.Sin(phase*Mathf.PI*2+i*Mathf.PI)*.17f*move);if(Interacting)target=new Vector3(side*.19f,.15f+Mathf.Sin(phase*12+i)*.015f,-.53f);JointMotion.Solve(transform,a.upper,a.lower,a.end,transform.TransformPoint(target)+up*bob,transform.TransformDirection(new Vector3(side,-.35f,.5f)),a.a,a.b);}
 }
 void OnDestroy(){foreach(var m in materials)if(m!=null)Destroy(m);}
}
